package com.aydindemir.redis; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.cache.CacheManager; import com.aydindemir.redis.redis.cache.ProductCacheService; import com.aydindemir.redis.support.RedisTestContainerSupport;
@SpringBootTest class ProductCacheIntegrationTest extends RedisTestContainerSupport { @Autowired ProductCacheService s; @Autowired CacheManager cm; @Test void secondReadHitsCache(){cm.getCache(ProductCacheService.CACHE_NAME).clear();long before=s.repositoryLoadCount();s.get(1L);long first=s.repositoryLoadCount();s.get(1L);long second=s.repositoryLoadCount();assertThat(first).isEqualTo(before+1);assertThat(second).isEqualTo(first);} }
